import { v } from 'convex/values';
import {
  internalAction,
  internalMutation,
  internalQuery,
  mutation,
  query,
} from './_generated/server';
import { conversationId, playerId } from './aiTown/ids';
import { DEFAULT_NAME, HUMAN_CHAT_AUTHOR_ID } from './constants';
import { internal } from './_generated/api';
import { chatCompletion, fetchEmbedding, LLMMessage } from './util/llm';

/**
 * Human↔NPC chat persistence + prompt context.
 * LLM replies are generated by the standalone chat-server; the frontend
 * calls these mutations asynchronously so Convex load never blocks the UI.
 */

const PROMPT_HISTORY_LIMIT = 5;

export const activeChat = query({
  args: {
    worldId: v.id('worlds'),
  },
  handler: async (ctx, args) => {
    const human = DEFAULT_NAME;
    const chat = await ctx.db
      .query('humanConversations')
      .withIndex('world_human_status', (q) =>
        q.eq('worldId', args.worldId).eq('human', human).eq('status', 'active'),
      )
      .first();
    if (!chat) {
      return null;
    }
    return {
      conversationId: chat.conversationId,
      playerId: chat.playerId,
      humanPlayerId: chat.humanPlayerId,
      created: chat.created,
    };
  },
});

/**
 * Character traits + historical conversation summaries for human↔NPC prompts.
 * - agentHistorySummaries: this NPC's past chats with other agents
 * - humanHistorySummaries: this NPC's past chats with the human player
 */
export const promptContext = query({
  args: {
    worldId: v.id('worlds'),
    playerId,
  },
  handler: async (ctx, args) => {
    const npcDescription = await ctx.db
      .query('playerDescriptions')
      .withIndex('worldId', (q) => q.eq('worldId', args.worldId).eq('playerId', args.playerId))
      .unique();
    if (!npcDescription) {
      throw new Error(`找不到要聊天的角色`);
    }

    const world = await ctx.db.get(args.worldId);
    const agent = world?.agents.find((a) => a.playerId === args.playerId);
    const agentDescription = agent
      ? await ctx.db
          .query('agentDescriptions')
          .withIndex('worldId', (q) => q.eq('worldId', args.worldId).eq('agentId', agent.id))
          .first()
      : null;

    const conversationMemories = await ctx.db
      .query('memories')
      .withIndex('playerId_type', (q) =>
        q.eq('playerId', args.playerId).eq('data.type', 'conversation'),
      )
      .order('desc')
      .take(40);

    const agentHistorySummaries: string[] = [];
    const humanHistorySummaries: string[] = [];
    for (const memory of conversationMemories) {
      if (memory.data.type !== 'conversation') continue;
      const withHuman = memory.data.playerIds.includes(HUMAN_CHAT_AUTHOR_ID);
      if (withHuman) {
        if (humanHistorySummaries.length < PROMPT_HISTORY_LIMIT) {
          humanHistorySummaries.push(memory.description);
        }
      } else if (agentHistorySummaries.length < PROMPT_HISTORY_LIMIT) {
        agentHistorySummaries.push(memory.description);
      }
      if (
        agentHistorySummaries.length >= PROMPT_HISTORY_LIMIT &&
        humanHistorySummaries.length >= PROMPT_HISTORY_LIMIT
      ) {
        break;
      }
    }

    // Fallback: if no remembered human chats yet, surface recent ended transcripts.
    if (humanHistorySummaries.length === 0) {
      const pastChats = await ctx.db
        .query('humanConversations')
        .withIndex('world_human_status', (q) =>
          q.eq('worldId', args.worldId).eq('human', DEFAULT_NAME).eq('status', 'ended'),
        )
        .collect();
      const withThisNpc = pastChats
        .filter((c) => c.playerId === args.playerId)
        .sort((a, b) => b.created - a.created)
        .slice(0, PROMPT_HISTORY_LIMIT);

      for (const chat of withThisNpc) {
        const messages = await ctx.db
          .query('messages')
          .withIndex('conversationId', (q) =>
            q.eq('worldId', args.worldId).eq('conversationId', chat.conversationId),
          )
          .collect();
        if (messages.length === 0) continue;
        const snippet = messages
          .slice(-6)
          .map((m) => {
            const who = m.author === HUMAN_CHAT_AUTHOR_ID ? DEFAULT_NAME : npcDescription.name;
            return `${who}: ${m.text}`;
          })
          .join(' / ');
        humanHistorySummaries.push(
          `与 ${DEFAULT_NAME} 在 ${new Date(chat.created).toLocaleString()} 的对话摘录：${snippet}`,
        );
      }
    }

    const identity = agentDescription?.identity ?? npcDescription.description;
    const description = npcDescription.description;
    const plan = agentDescription?.plan;

    return {
      playerId: args.playerId,
      npcName: npcDescription.name,
      // 角色自身特性：人设 / 简介 / 目标
      identity,
      description,
      plan,
      // 与其他 agent 的历史对话摘要
      agentHistorySummaries,
      // 与玩家的历史对话摘要
      humanHistorySummaries,
    };
  },
});

export const startChat = mutation({
  args: {
    worldId: v.id('worlds'),
    playerId,
    // Client-generated id (hc:uuid) so local UI and Convex stay in sync.
    conversationId: v.optional(conversationId),
  },
  handler: async (ctx, args) => {
    const started = Date.now();
    const human = DEFAULT_NAME;

    // Avoid reading `worlds` (high OCC under simulation). Validate via description.
    const npcDescription = await ctx.db
      .query('playerDescriptions')
      .withIndex('worldId', (q) => q.eq('worldId', args.worldId).eq('playerId', args.playerId))
      .unique();
    if (!npcDescription) {
      throw new Error(`找不到要聊天的角色`);
    }

    const existing = await ctx.db
      .query('humanConversations')
      .withIndex('world_human_status', (q) =>
        q.eq('worldId', args.worldId).eq('human', human).eq('status', 'active'),
      )
      .collect();

    for (const chat of existing) {
      if (chat.playerId === args.playerId) {
        // Same NPC already active — keep the existing conversationId so prior
        // messages stay linked. Client must adopt this id for persistMessage.
        if (args.conversationId && args.conversationId !== chat.conversationId) {
          console.log(
            `[timing] humanChat.startChat.reuseDifferentId requested=${args.conversationId} existing=${chat.conversationId}`,
          );
        }
        console.log(
          `[timing] humanChat.startChat.total: ${Date.now() - started}ms (reuse ${chat.conversationId})`,
        );
        return {
          conversationId: chat.conversationId,
          playerId: chat.playerId,
          humanPlayerId: chat.humanPlayerId,
        };
      }
      await ctx.db.patch(chat._id, { status: 'ended' });
      await ctx.scheduler.runAfter(0, internal.humanChat.rememberHumanConversation, {
        worldId: args.worldId,
        playerId: chat.playerId,
        conversationId: chat.conversationId,
      });
    }

    const conversationIdValue = args.conversationId ?? `hc:${crypto.randomUUID()}`;
    const created = Date.now();
    await ctx.db.insert('humanConversations', {
      worldId: args.worldId,
      human,
      playerId: args.playerId,
      humanPlayerId: HUMAN_CHAT_AUTHOR_ID,
      conversationId: conversationIdValue,
      created,
      status: 'active',
    });
    console.log(
      `[timing] humanChat.startChat.total: ${Date.now() - started}ms (new ${conversationIdValue})`,
    );
    return {
      conversationId: conversationIdValue,
      playerId: args.playerId,
      humanPlayerId: HUMAN_CHAT_AUTHOR_ID,
    };
  },
});

export const endChat = mutation({
  args: {
    worldId: v.id('worlds'),
  },
  handler: async (ctx, args) => {
    const human = DEFAULT_NAME;
    const existing = await ctx.db
      .query('humanConversations')
      .withIndex('world_human_status', (q) =>
        q.eq('worldId', args.worldId).eq('human', human).eq('status', 'active'),
      )
      .collect();
    for (const chat of existing) {
      await ctx.db.patch(chat._id, { status: 'ended' });
      await ctx.scheduler.runAfter(0, internal.humanChat.rememberHumanConversation, {
        worldId: args.worldId,
        playerId: chat.playerId,
        conversationId: chat.conversationId,
      });
    }
  },
});

export const persistMessage = mutation({
  args: {
    worldId: v.id('worlds'),
    conversationId,
    author: playerId,
    text: v.string(),
    messageUuid: v.string(),
  },
  handler: async (ctx, args) => {
    const text = args.text.trim();
    if (!text) {
      throw new Error(`消息不能为空`);
    }
    const chat = await ctx.db
      .query('humanConversations')
      .withIndex('conversationId', (q) => q.eq('conversationId', args.conversationId))
      .unique();
    if (!chat || chat.worldId !== args.worldId) {
      // Chat row may not have landed yet if startChat is still queued — insert anyway
      // only when we can verify authors against expected human/npc ids from args.
      // Safer: require the conversation row. Retry from client if missing.
      throw new Error(`对话不存在或尚未写入`);
    }
    if (chat.status !== 'active') {
      throw new Error(`对话已结束`);
    }
    if (args.author !== chat.humanPlayerId && args.author !== chat.playerId) {
      throw new Error(`无效的消息作者`);
    }
    const existing = await ctx.db
      .query('messages')
      .withIndex('messageUuid', (q) =>
        q.eq('conversationId', args.conversationId).eq('messageUuid', args.messageUuid),
      )
      .unique();
    if (existing) {
      return { ok: true, deduped: true };
    }
    await ctx.db.insert('messages', {
      worldId: args.worldId,
      conversationId: args.conversationId,
      author: args.author,
      text,
      messageUuid: args.messageUuid,
    });
    return { ok: true, deduped: false };
  },
});

/** Kept for internal/tests; human UI no longer calls this. */
export const insertMessage = internalMutation({
  args: {
    worldId: v.id('worlds'),
    conversationId,
    author: playerId,
    text: v.string(),
    messageUuid: v.string(),
  },
  handler: async (ctx, args) => {
    await ctx.db.insert('messages', {
      worldId: args.worldId,
      conversationId: args.conversationId,
      author: args.author,
      text: args.text,
      messageUuid: args.messageUuid,
    });
  },
});

export const loadHumanConversationForMemory = internalQuery({
  args: {
    worldId: v.id('worlds'),
    playerId,
    conversationId,
  },
  handler: async (ctx, args) => {
    const chat = await ctx.db
      .query('humanConversations')
      .withIndex('conversationId', (q) => q.eq('conversationId', args.conversationId))
      .unique();
    if (!chat || chat.worldId !== args.worldId || chat.playerId !== args.playerId) {
      return null;
    }

    const existingMemory = await ctx.db
      .query('memories')
      .withIndex('playerId_type', (q) =>
        q.eq('playerId', args.playerId).eq('data.type', 'conversation'),
      )
      .order('desc')
      .take(30);
    const alreadyRemembered = existingMemory.some(
      (m) => m.data.type === 'conversation' && m.data.conversationId === args.conversationId,
    );
    if (alreadyRemembered) {
      return { alreadyRemembered: true as const };
    }

    const npcDescription = await ctx.db
      .query('playerDescriptions')
      .withIndex('worldId', (q) => q.eq('worldId', args.worldId).eq('playerId', args.playerId))
      .unique();
    if (!npcDescription) {
      return null;
    }

    const world = await ctx.db.get(args.worldId);
    const agent = world?.agents.find((a) => a.playerId === args.playerId);

    const messages = await ctx.db
      .query('messages')
      .withIndex('conversationId', (q) =>
        q.eq('worldId', args.worldId).eq('conversationId', args.conversationId),
      )
      .collect();

    return {
      alreadyRemembered: false as const,
      npcName: npcDescription.name,
      agentId: agent?.id ?? 'a:0',
      created: chat.created,
      messages: messages.map((m) => ({
        author: m.author,
        text: m.text,
        _creationTime: m._creationTime,
      })),
    };
  },
});

/**
 * After a human↔NPC chat ends, summarize it into the NPC's memory store
 * so future prompts can include "与我的历史对话摘要".
 */
export const rememberHumanConversation = internalAction({
  args: {
    worldId: v.id('worlds'),
    playerId,
    conversationId,
  },
  handler: async (ctx, args) => {
    const data = await ctx.runQuery(internal.humanChat.loadHumanConversationForMemory, args);
    if (!data) {
      return;
    }
    if (data.alreadyRemembered) {
      return;
    }
    if (data.messages.length === 0) {
      return;
    }

    const llmMessages: LLMMessage[] = [
      {
        role: 'user',
        content: `你是 ${data.npcName}，刚刚和 ${DEFAULT_NAME} 结束了一次对话。请用第一人称（“我”）从 ${data.npcName} 的视角用简体中文总结这次对话，并说明你喜欢还是不喜欢这次交流。`,
      },
    ];
    for (const message of data.messages) {
      const authorName = message.author === HUMAN_CHAT_AUTHOR_ID ? DEFAULT_NAME : data.npcName;
      const recipientName = message.author === HUMAN_CHAT_AUTHOR_ID ? data.npcName : DEFAULT_NAME;
      llmMessages.push({
        role: 'user',
        content: `${authorName} to ${recipientName}: ${message.text}`,
      });
    }
    llmMessages.push({ role: 'user', content: 'Summary:' });

    const { content } = await chatCompletion({
      messages: llmMessages,
      max_tokens: 500,
    });
    const description = `与 ${DEFAULT_NAME} 在 ${new Date(data.created).toLocaleString()} 的对话：${content}`;

    const importanceRaw = await chatCompletion({
      messages: [
        {
          role: 'user',
          content: `请按 0 到 9 打分，0 表示非常日常（例如刷牙、整理床铺），9 表示极其深刻（例如分手、被大学录取）。给下面这条记忆的情感强度打分。
      记忆：${description}
      只回答 0 到 9 的数字，例如 "5"`,
        },
      ],
      temperature: 0.0,
      max_tokens: 1,
    });
    let importance = parseFloat(importanceRaw.content);
    if (isNaN(importance)) {
      importance = +(importanceRaw.content.match(/\d+/)?.[0] ?? NaN);
    }
    if (isNaN(importance)) {
      importance = 5;
    }

    const { embedding } = await fetchEmbedding(description);
    await ctx.runMutation(internal.agent.memory.insertMemory, {
      agentId: data.agentId,
      playerId: args.playerId,
      description,
      importance,
      lastAccess: data.messages[data.messages.length - 1]._creationTime,
      data: {
        type: 'conversation' as const,
        conversationId: args.conversationId,
        playerIds: [HUMAN_CHAT_AUTHOR_ID],
      },
      embedding,
    });
    console.log(
      `[timing] humanChat.rememberHumanConversation ok conversationId=${args.conversationId} player=${args.playerId}`,
    );
  },
});
